import ghidra.app.decompiler.*; import ghidra.app.script.GhidraScript; import ghidra.program.model.address.*; import ghidra.program.model.listing.*;
public class Find414ef0Callers extends GhidraScript { public void run()throws Exception{DecompInterface d=new DecompInterface();d.openProgram(currentProgram);Function t=getFunctionAt(toAddr(0x00414ef0L));println("TARGET "+t);for(Reference r:t.getSymbol().getReferences()){Function f=getFunctionContaining(r.getFromAddress());println("CALL "+r.getFromAddress()+" "+(f==null?"<none>":f.getName()));if(f!=null){DecompileResults z=d.decompileFunction(f,120,monitor);if(z.getDecompiledFunction()!=null)println(z.getDecompiledFunction().getC());}}d.dispose();}}
